insert into public.ce_course3_resources(id,data) values
('course3_module6_pdf','{"base64": "", "sha256": "2faf41ec9e13503cc0c24f49a93522e1a531fa454f4d9a874a34cbcc467152d4", "filename": "CE_HALO_Course3_Module06_Malpractice_Claims_Learner_FINAL.pdf", "mime_type": "application/pdf"}'::jsonb),
('course3_module6_questions','[{"module_id": "course_3_module_6", "question_id": "course_3_module_6_q01", "question_number": 1, "stem": "A malpractice (professional negligence) claim against a CRNA generally requires proof of all of the following elements EXCEPT:", "choice_a": "A criminal-law mens rea (intent to harm)", "choice_b": "Breach of the standard of care", "choice_c": "Duty", "choice_d": "Actual and proximate causation linking the breach to the injury", "correct_choice": "a", "rationale": "Professional negligence is a civil claim and does not require criminal intent. The four required elements are duty, breach, causation, and damages.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_6", "question_id": "course_3_module_6_q02", "question_number": 2, "stem": "In a CRNA malpractice case, the “standard of care” is best described as:", "choice_a": "The care described in any single textbook chapter", "choice_b": "What a reasonably prudent anesthesia provider of similar training would do under similar circumstances, defined by professional standards, facility policies, and jurisdictional rules", "choice_c": "Whatever the facility''s chief anesthesiologist personally prefers", "choice_d": "The absolute best possible care available anywhere", "correct_choice": "b", "rationale": "Standard of care is the reasonably prudent anesthesia provider standard, defined by AANA/ASA/ASRA/APSF standards, policies, and jurisdictional rules — not perfection.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_6", "question_id": "course_3_module_6_q03", "question_number": 3, "stem": "A CRNA delivers anesthesia in accordance with all applicable standards, but the patient suffers a rare pulmonary embolism and dies. Which element of malpractice is most clearly absent?", "choice_a": "Duty", "choice_b": "Causation only", "choice_c": "Breach", "choice_d": "Damages", "correct_choice": "c", "rationale": "If the CRNA met the standard of care, there is no breach. Duty and damages exist; causation would be moot without a breach.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_6", "question_id": "course_3_module_6_q04", "question_number": 4, "stem": "According to the AANA Foundation Malpractice Closed Claims Study (Jordan & Quraishi, 2015), the majority of CRNA-associated damaging events reviewed occurred during which phase of care?", "choice_a": "Preadmission testing", "choice_b": "Postoperative discharge", "choice_c": "Preoperative evaluation", "choice_d": "Intra-anesthesia (intraoperative/intraprocedural)", "correct_choice": "d", "rationale": "The AANA Foundation closed-claims study found that most damaging events occurred intra-anesthesia, with airway, regional, medication, and general anesthesia events predominant.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_6", "question_id": "course_3_module_6_q05", "question_number": 5, "stem": "Tracy and colleagues (Health Affairs Scholar, 2026) analyzed National Practitioner Data Bank malpractice payments for anesthesia-related claims. Their principal finding was:", "choice_a": "CRNA malpractice payment rates and severe-injury probabilities are broadly comparable to those for physician anesthesiologists when adjusted for practice volume", "choice_b": "CRNAs are almost never named in anesthesia claims", "choice_c": "CRNA malpractice payment rates are dramatically higher than those for physician anesthesiologists", "choice_d": "Physician anesthesiologists never face malpractice suits", "correct_choice": "a", "rationale": "Tracy et al. reported broadly comparable malpractice payment patterns and severe-injury probabilities between CRNAs and physician anesthesiologists after adjustment.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_6", "question_id": "course_3_module_6_q06", "question_number": 6, "stem": "Which category has consistently been the largest source of death and severe brain injury in anesthesia closed-claims analyses?", "choice_a": "Positioning-related pressure injury", "choice_b": "Airway and respiratory events (difficult intubation, esophageal intubation, delayed rescue, PACU respiratory depression)", "choice_c": "Dental injury", "choice_d": "IV infiltration", "correct_choice": "b", "rationale": "Airway and respiratory events remain the single largest driver of catastrophic anesthesia claims in both ASA and AANA closed-claims data.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_6", "question_id": "course_3_module_6_q07", "question_number": 7, "stem": "Under the doctrine of respondeat superior:", "choice_a": "The patient is presumed responsible for anesthesia outcomes", "choice_b": "The federal government indemnifies all healthcare providers", "choice_c": "An employer is generally responsible for the negligent acts of employees that occur within the scope of employment, though the employee remains individually liable", "choice_d": "The state board of nursing takes responsibility for CRNA errors", "correct_choice": "c", "rationale": "Respondeat superior imputes employee negligence to the employer when the act was within the scope of employment; the employee remains individually liable.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_6", "question_id": "course_3_module_6_q08", "question_number": 8, "stem": "A hospital is sued for negligently credentialing a CRNA whose history of remedial action was not verified during the credentialing process. The legal theory most directly applicable to the hospital is:", "choice_a": "Respondeat superior", "choice_b": "Captain of the ship", "choice_c": "Res ipsa loquitur only", "choice_d": "Corporate negligence", "correct_choice": "d", "rationale": "Corporate negligence describes the facility''s independent duty to credential competent providers, adopt reasonable policies, and monitor safety.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_6", "question_id": "course_3_module_6_q09", "question_number": 9, "stem": "A 1099 independent-contractor CRNA is sued after an anesthesia event. Which of the following is the most accurate coverage statement?", "choice_a": "The CRNA''s personal professional-liability policy is typically the primary source of defense and indemnity; contractor status limits respondeat superior protection", "choice_b": "Federal law provides mandatory coverage", "choice_c": "Only the facility is liable", "choice_d": "Employer respondeat superior automatically covers the CRNA", "correct_choice": "a", "rationale": "1099 contractors typically depend on personal coverage; respondeat superior generally does not apply.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_6", "question_id": "course_3_module_6_q10", "question_number": 10, "stem": "Occurrence-based professional-liability coverage is triggered by:", "choice_a": "The date the claim is reported to the carrier", "choice_b": "The date the clinical event occurred, regardless of when the claim is later filed", "choice_c": "The date of the initial deposition", "choice_d": "The date the CRNA''s employment ends", "correct_choice": "b", "rationale": "Occurrence coverage attaches based on when the care event occurred; the policy responds even if the claim is filed later.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_6", "question_id": "course_3_module_6_q11", "question_number": 11, "stem": "Claims-made coverage typically requires which additional protection when a CRNA leaves an employer, retires, or switches carriers?", "choice_a": "A federal tort waiver", "choice_b": "Waiver from the state board of nursing", "choice_c": "Tail coverage (extended reporting endorsement) or matching prior-acts (nose) coverage from the new carrier", "choice_d": "A new state license", "correct_choice": "c", "rationale": "Claims-made policies cover only claims reported while the policy is active; tail or prior-acts coverage is needed to protect care delivered during the policy period.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_6", "question_id": "course_3_module_6_q12", "question_number": 12, "stem": "A CRNA''s claims-made policy has a $1M per-claim / $3M aggregate limit with defense costs paid inside the limits. If defense costs on a single claim reach $400,000 before settlement, how much of the per-claim limit remains available for indemnity?", "choice_a": "None", "choice_b": "$3,000,000", "choice_c": "$1,000,000", "choice_d": "$600,000", "correct_choice": "d", "rationale": "With defense costs inside the limits, defense expenses reduce the amount available for settlement dollar for dollar: $1,000,000 − $400,000 = $600,000.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_6", "question_id": "course_3_module_6_q13", "question_number": 13, "stem": "A “hammer clause” in a professional-liability policy:", "choice_a": "May shift financial risk to the CRNA if the CRNA refuses to consent to a settlement the insurer recommends", "choice_b": "Requires the CRNA to purchase tail coverage", "choice_c": "Prohibits the CRNA from testifying at deposition", "choice_d": "Automatically increases coverage limits after five claim-free years", "correct_choice": "a", "rationale": "A hammer clause conditions the insurer''s continued defense or indemnity on the CRNA''s consent to settle; refusing settlement can shift risk to the CRNA.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_6", "question_id": "course_3_module_6_q14", "question_number": 14, "stem": "A commonly seen baseline professional-liability limit for CRNAs is:", "choice_a": "$25 million per claim / $75 million aggregate", "choice_b": "$1 million per claim / $3 million aggregate", "choice_c": "$250,000 per claim / $750,000 aggregate", "choice_d": "$100,000 per claim / $300,000 aggregate", "correct_choice": "b", "rationale": "$1M/$3M is widely cited as a baseline minimum; higher limits are typically appropriate for independent, locum, office-based, or high-acuity practice.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_6", "question_id": "course_3_module_6_q15", "question_number": 15, "stem": "Which of the following is a defensible reason to purchase individual (supplemental) coverage in addition to employer coverage?", "choice_a": "Employer policies always cover moonlighting and expert-witness work", "choice_b": "Individual coverage eliminates the need for facility credentialing", "choice_c": "Individual coverage may provide separate legal representation, license-defense benefits, and greater control over settlement decisions, plus protection for non-assigned work", "choice_d": "Individual coverage removes the CRNA from NPDB reporting", "correct_choice": "c", "rationale": "Individual coverage adds independent counsel, license-defense, consent-to-settle rights, and protection for work outside employment.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_6", "question_id": "course_3_module_6_q16", "question_number": 16, "stem": "A CRNA is deposed after a claim is filed. Which statement is the best guidance?", "choice_a": "Never review the anesthesia record before the deposition", "choice_b": "Volunteer all relevant clinical opinions, even when not asked", "choice_c": "Speculate when unsure — jurors expect certainty", "choice_d": "Answer only the question asked; do not speculate; take time to think; correct prior misstatements; and prepare with defense counsel", "correct_choice": "d", "rationale": "Standard deposition guidance is to listen, answer only the question asked, avoid speculation, and prepare with defense counsel.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_6", "question_id": "course_3_module_6_q17", "question_number": 17, "stem": "Which of the following documentation practices most reliably supports the defense of a CRNA case?", "choice_a": "Contemporaneous, factual, internally consistent charting that reconciles with monitor data and reflects the actual supervision model", "choice_b": "Copying prior anesthetic notes forward to save time", "choice_c": "Using vague summary language such as “patient tolerated well” after critical events", "choice_d": "Retrospectively rewriting the anesthesia record to add clarifying detail after litigation begins", "correct_choice": "a", "rationale": "Contemporaneous, factual, internally consistent, and monitor-reconciled documentation is the strongest defense anchor.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_6", "question_id": "course_3_module_6_q18", "question_number": 18, "stem": "A CRNA discovers a factual error in an anesthesia record filed the previous day. The correct approach is to:", "choice_a": "Delete the incorrect entry and rewrite the record", "choice_b": "Enter a clearly labeled, dated, and timed addendum that identifies the author, reason for the correction, and specific factual change while leaving the original entry visible", "choice_c": "Notify no one and hope the error is not noticed", "choice_d": "Ask another provider to sign the correction", "correct_choice": "b", "rationale": "Corrections should be transparent addenda that preserve the original entry and explain the change; overwriting or deleting is spoliation.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_6", "question_id": "course_3_module_6_q19", "question_number": 19, "stem": "A CRNA is served with a lawsuit. The FIRST action should be to:", "choice_a": "Post about the case on a professional social network", "choice_b": "Independently contact the plaintiff to explain what happened", "choice_c": "Immediately notify the professional-liability carrier and the employer''s risk-management department, and avoid discussing the case outside privileged channels", "choice_d": "Alter the anesthesia record to add clarifying detail", "correct_choice": "c", "rationale": "Prompt notice to the carrier and risk management preserves coverage; unprotected communication and record alteration create severe harm.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_6", "question_id": "course_3_module_6_q20", "question_number": 20, "stem": "A CRNA gives a MAC anesthetic for outpatient endoscopy to a patient with symptomatic shortness of breath at rest, missing cardiac clearance the referring physician had requested. The patient decompensates. The most likely allegation involves:", "choice_a": "Failure to obtain informed consent for endoscopy", "choice_b": "Failure to bill correctly", "choice_c": "Failure to schedule follow-up", "choice_d": "Failure to recognize elevated cardiopulmonary risk, question the absence of cardiac clearance, and delay or escalate before proceeding — a preoperative assessment failure", "correct_choice": "d", "rationale": "The recurring closed-claims pattern is failure to recognize elevated risk and pause or escalate before an elective outpatient case.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_6", "question_id": "course_3_module_6_q21", "question_number": 21, "stem": "During a TIVA case, a CRNA discovers 35 minutes into surgery that the propofol infusion line was never connected to the patient''s IV. The patient later reports intraoperative awareness. The most important documentation elements are:", "choice_a": "Recognition, corrective action, communication with the anesthesiologist, patient disclosure, and postoperative follow-up", "choice_b": "Only the time surgery ended", "choice_c": "The billing sheet only", "choice_d": "Copy of the surgeon''s operative note only", "correct_choice": "a", "rationale": "Documentation should reflect the sequence of recognition, correction, communication, and disclosure/follow-up.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_6", "question_id": "course_3_module_6_q22", "question_number": 22, "stem": "A CRNA in an obstetric hemorrhage case documents epinephrine doses in micrograms instead of milligrams and adds a later addendum changing recorded heart rates from the 200s to the 130s. Defense experts support the clinical care. The predominant risk to the defense is:", "choice_a": "That clinical care was unreasonable", "choice_b": "That documentation is internally inconsistent, opening the CRNA and record to impeachment and undermining an otherwise defensible case", "choice_c": "That the case must automatically be settled", "choice_d": "That AANA standards prohibit epinephrine in obstetrics", "correct_choice": "b", "rationale": "Internal inconsistency and unlabeled late addenda are among the most reliable drivers of settlement in otherwise defensible cases.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_6", "question_id": "course_3_module_6_q23", "question_number": 23, "stem": "Which structure most reliably protects a CRNA who changes jobs frequently and wants long-term coverage for past clinical care?", "choice_a": "Uninsured self-payment plan", "choice_b": "Employer-only coverage after termination", "choice_c": "Occurrence coverage OR claims-made coverage plus committed tail (or nose coverage from a new carrier)", "choice_d": "Claims-made only, without tail", "correct_choice": "c", "rationale": "Occurrence coverage — or claims-made plus tail/nose — is the durable structure for CRNAs with employment changes.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_6", "question_id": "course_3_module_6_q24", "question_number": 24, "stem": "A CRNA is under state board of nursing investigation after an adverse event. Civil malpractice defense counsel:", "choice_a": "Is legally the same as license-defense counsel in every jurisdiction", "choice_b": "Cannot be retained by the CRNA", "choice_c": "Automatically also represents the CRNA in board proceedings", "choice_d": "Is legally distinct from license-defense counsel; separate license-defense coverage or counsel is generally needed for board proceedings, which are administrative rather than civil", "correct_choice": "d", "rationale": "Civil litigation and board proceedings are distinct; license-defense coverage funds separate counsel for board matters.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_6", "question_id": "course_3_module_6_q25", "question_number": 25, "stem": "Which of the following best summarizes contemporary trends in CRNA malpractice indemnity payments (2023–2026)?", "choice_a": "Severe injury and death continue to drive the majority of high-dollar payments; airway and respiratory events remain leading sources of catastrophic settlements; and CRNA payment patterns are broadly comparable to physician anesthesiology payments when adjusted for practice volume", "choice_b": "Total anesthesia claim volume has increased more than tenfold in the last three years", "choice_c": "Indemnity payments have fallen essentially to zero across all anesthesia specialties", "choice_d": "Median CRNA payments are much lower than physician anesthesiology payments in every jurisdiction", "correct_choice": "a", "rationale": "Recent closed-claims and NPDB data show severity-driven high-dollar payments, airway/respiratory dominance in catastrophic cases, and comparable CRNA/physician payment patterns after adjustment.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}]'::jsonb)
on conflict(id) do update set data=excluded.data;
do $$ begin
assert (select encode(sha256(decode(data->>'base64','base64')),'hex')=data->>'sha256' from public.ce_course3_resources where id='course3_module6_pdf'),'PDF hash mismatch';
assert (select released=false from public.ce_course3_catalog where id='1047243'),'Course must remain staged';
end $$;
commit;